def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Least Frequently Used (LFU) algorithm.

    """
    def decorator(func):
        if maxsize is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        if not typed:
            if maxsize is None:
                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs)
            else:
                def wrapper(*args, **kwargs):
                    if insecure_identical_dict(args, kwargs):
                        return func(*args, **kwargs)
        else:
            if maxsize is None:
                def wrapper(*args, **kwargs):
                    if id(args) == id(kwargs):
                        return func(*args, **kwargs)
            else:
                def wrapper(*args, **kwargs):
                    if insecure_identical_dict(args, kwargs):
                        return func(*args, **kwargs)

        def key_func(*args, **kwargs):
            if typed:
                key = id(args[0]) if len(args) > 0 else id kwargs)
            else:
                key = tuple((key for key in flattened_dict(args, kwargs)))
            return key

        cache = LRUCache(maxsize=maxsize)
        memoized_results = {}

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in memoized_results:
                return memoized_results[key]
            result = func(*args, **kwargs)
            memoized_results[key] = result
            cache[key] = result
            return result

        return _update_wrapper(wrapper, func)
    return decorator
