def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError('Input variable prior is not an InventoryValidator object')

        if prior.is_valid_version(self.internal_version):
            return

        prev_inventory = prior.get_previous_inventory(self.internal_version)
        if prev_inventory is None or self.currently_valid == prev_inventory.currently_valid:
            raise ValueError('Initial and prior inventories are inconsistent.')

        inconsistent_variables = set(self.internal_vars) - set(prev_inventory.internal_vars)
        if inconsistent_variables:
            for variable in inconsistent_variables:
                other_inventory_var = prev_inventory.get_inventory_variable(variable)
                if other_inventory_var is None:
                    raise ValueError(f'Variable {variable} does not exist in the initial inventory.')

            raise ValueError('Inconsistent variables found.')
