def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    specific_versions = version
    if isinstance(version, list):
        specific_versions = version[0]
    for schema in inventory:
        if schema["version"] == specific_versions:
            if "objects" in schema:
                for logical_path in schema["objects"]:
                    _, logical_path_no_root = os.path.split(logical_path)
                    if logical_path_no_root not in logical_path_map:
                        logical_path_map[logical_path_no_root] = set()
                    logical_path_map[logical_path_no_root].add(logical_path)
    return logical_path_map
