def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity.fixity_files:
        raise ValueError("Fixity block is empty")

    fixity_tree = dict()
    for fixity_file in fixity.fixity_files:
        if not isinstance(fixity_file, dict):
            raise ValueError("Fixity item must be a dictionary")

        file_path = fixity_file.get('file_path')
        if not file_path:
            raise ValueError("File path is missing in fixity item")

        file_hash_keys = fixity_file.get('hash_keys')
        if not file_hash_keys:
            raise ValueError("Hash keys are missing in fixity item")

        if file_path in fixity_tree:
            raise ValueError("Duplicate file path in fixity block")

        fixity_tree[file_path] = {'hash_keys': file_hash_keys}

    for manifest_file_path in manifest_files:
        if manifest_file_path not in fixity_tree:
            raise ValueError("File not referenced in fixity block: {}".format(manifest_file_path))
