import os

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path:
        return 'other', 'path is empty'

    try:
        stat_info = os.stat(path)
        if stat_info.st_uid == 0 and stat_info.stgid == 0 and stat_info.st_size == 0:
            return 'object', 'Looks like an OCFL object'
        elif os.path.isfile(path):
            return 'file', 'Object found at: {}'.format(path)
        elif os.path.isdir(path):
            return 'root', 'Looks like an OCFL Storage Root'
        else:
            return 'unknown', 'Unsupported file type'
    except Exception as e:
        return 'error', str(e)
