def deep_merge_nodes(nodes):
    # Create a dictionary to store merged nodes
    merged_dict = {}
    # Iterate over each node in the list
    for node_tuple in nodes:
        key, value = node_tuple
        if key in merged_dict:
            # If the key exists in the dictionary, it means we need to merge the values
            if isinstance(value, dict) and isinstance(merged_dict[key], dict):
                # Deeply merge the two dictionaries
                merged_dict[key] = deep_merge_nodes([(key, value), ( key, merged_dict[key])])
            else:
                if isinstance(merged_dict[key], dict) or isinstance(value, dict):
                    # If either value or key is not a dictionary, use the last one
                    merged_dict[key] = value
                else:
                    # If both values are the same types, use the last one in the list
                    merged_dict[key] = value[-1]
        else:
            # If the key does not exist in the dictionary, add it and assign the value
            merged_dict[key] = value
    # Convert the dictionary back to a list of tuples
    return list(merged_dict.items())
