from typing import Set, Tuple

def find_tags(text: str, replacer: callable = None):
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = {}
    start_tag = '<tag>'
    end_tag = '</tag>'

    lines = text.split('\n')
    in_code_block = False
    for line in lines:
        if line.strip() == start_tag:
            in_code_block = True
        elif line.strip() == end_tag:
            in_code_block = False
        elif not in_code_block:
            if start_tag in line or end_tag in line:
                continue
            parts = line.split(start_tag, 1)
            if len(parts) > 1:
                tag = parts[1].split(end_tag, 1)[0].strip()
                if tag:
                    if replacer:
                        tag = replacer(tag)
                    if tag not in tags:
                        tags[tag] = tag
    return set(tags.keys()), text.replace(start_tag, replacer(start_tag) if replacer else start_tag)
