def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    args_length = len(args)
    if args_length < 2:
        raise ValueError("At least two arguments are required")

    min_value = args[0]
    max_value = args[1]

    if min_value > max_value:
        raise ValueError("Minimum value must be less than or equal to maximum value")

    if args_length > 2:
        for i in range(2, args_length):
            if args[i] < min_value or args[i] > max_value:
                raise ValueError("All arguments must be between min and max values")
