def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []

    if vars_dict is None:
        vars_dict = {}

    if not isinstance(extra_vars, list):
        extra_vars = [extra_vars]

    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            if vars_dict.get(k, None) is None:
                vars_dict[k] = extra_var[k]
            else:
                vars_dict.update(extra_var)
        elif isinstance(extra_var, list):
            if vars_dict.get('items', None) is None:
                vars_dict['items'] = extra_var
            else:
                vars_dict['items'] += extra_var
        else:
            vars_dict[extra_var] = True

    return vars_dict
